CREATE TYPE public.app_role AS ENUM ('admin','moderator','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, items jsonb NOT NULL, total numeric(12,2) NOT NULL, address jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'awaiting_payment' CHECK(status IN ('awaiting_payment','processing','shipped','out_for_delivery','delivered','cancelled')), payment_status text NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','paid','refunded')), tracking text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_orders ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.order_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id), actor_id uuid, stage text NOT NULL, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.order_events TO authenticated; GRANT ALL ON public.order_events TO service_role;
ALTER TABLE public.order_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_order_events ON public.order_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders o WHERE o.id=order_id AND (o.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.kyc_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, reference text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), review_note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.kyc_cases TO authenticated; GRANT ALL ON public.kyc_cases TO service_role;
ALTER TABLE public.kyc_cases ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_kyc ON public.kyc_cases FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.return_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id), user_id uuid NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','rejected','received','closed')), review_note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.return_requests TO authenticated; GRANT ALL ON public.return_requests TO service_role;
ALTER TABLE public.return_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_returns ON public.return_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX one_open_return ON public.return_requests(order_id) WHERE status IN ('requested','approved','received');
CREATE FUNCTION public.process_order(_id uuid,_status text,_tracking text,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Staff access required'; END IF; SELECT * INTO o FROM public.orders WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF; IF _status <> 'cancelled' AND o.payment_status <> 'paid' THEN RAISE EXCEPTION 'Verified payment required before fulfilment'; END IF; IF NOT ((o.status='awaiting_payment' AND _status IN ('processing','cancelled')) OR (o.status='processing' AND _status IN ('shipped','cancelled')) OR (o.status='shipped' AND _status='out_for_delivery') OR (o.status='out_for_delivery' AND _status='delivered')) THEN RAISE EXCEPTION 'Invalid order transition'; END IF; IF _status='shipped' AND length(trim(_tracking))=0 THEN RAISE EXCEPTION 'Tracking reference required'; END IF; UPDATE public.orders SET status=_status,tracking=CASE WHEN length(trim(_tracking))>0 THEN trim(_tracking) ELSE tracking END WHERE id=_id; INSERT INTO public.order_events(order_id,actor_id,stage,note) VALUES(_id,auth.uid(),_status,_note); END $$;
REVOKE ALL ON FUNCTION public.process_order(uuid,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.process_order(uuid,text,text,text) TO authenticated;
CREATE FUNCTION public.review_case(_kind text,_id uuid,_status text,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE current_status text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Staff access required'; END IF; IF length(trim(_note))=0 THEN RAISE EXCEPTION 'Review note required'; END IF; IF _kind='kyc' THEN IF _status NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'Invalid identity decision'; END IF; UPDATE public.kyc_cases SET status=_status,review_note=_note WHERE id=_id AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'Pending case not found'; END IF; ELSIF _kind='return' THEN SELECT status INTO current_status FROM public.return_requests WHERE id=_id FOR UPDATE; IF NOT ((current_status='requested' AND _status IN ('approved','rejected')) OR (current_status='approved' AND _status='received') OR (current_status='received' AND _status='closed')) THEN RAISE EXCEPTION 'Invalid return transition'; END IF; UPDATE public.return_requests SET status=_status,review_note=_note WHERE id=_id; ELSE RAISE EXCEPTION 'Invalid case kind'; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_case(text,uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_case(text,uuid,text,text) TO authenticated;